export function fmtInt(n: number): string {
  return new Intl.NumberFormat("en-US").format(Math.round(n));
}

export function fmt1(n: number): string {
  return new Intl.NumberFormat("en-US", {
    maximumFractionDigits: 1,
    minimumFractionDigits: 0,
  }).format(n);
}

export function zeroOrOneByYear(year: number): number {
  const row = ACCESS_TIER_PATH.find((r) => r.year === year);
  if (!row) return 0;
  return row.zero + row.one;
}

export function statesByZeroDesc(): StateDesertRow[] {
  return [...STATE_DESERT_RANKS].sort((a, b) => b.zeroCounties - a.zeroCounties);
}

export function statesByZeroShareDesc(): StateDesertRow[] {
  return [...STATE_DESERT_RANKS].sort(
    (a, b) => b.zeroShareOfStatePct - a.zeroShareOfStatePct,
  );
}

