            </div>
          </ChartCard>

          <ChartCard
            title="Newspaper stock vs recent closures"
            subtitle="Stock path (left) ?? annual closures where timed (right)"
          >
            <div className="h-80 w-full">
              <ResponsiveContainer width="100%" height="100%">
                <ComposedChart data={newspaperClosure}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="year" tick={{ fontSize: 12 }} />
                  <YAxis
                    yAxisId="left"
                    tick={{ fontSize: 12 }}
                    domain={[4000, 8000]}
                  />
                  <YAxis
                    yAxisId="right"
                    orientation="right"
                    tick={{ fontSize: 12 }}
                    domain={[0, 160]}
                  />
                  <Tooltip />
                  <Legend />
                  <Area
                    yAxisId="left"
                    type="monotone"
                    dataKey="Newspapers"
                    stroke={NAVY}
                    fill={SKY}
                    fillOpacity={0.25}
                  />
                  <Line
                    yAxisId="right"
                    type="monotone"
                    dataKey="Closures"
                    stroke={ROSE}
                    strokeWidth={2.5}
                    connectNulls={false}
                    dot={{ r: 4 }}
                  />
                </ComposedChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {view === "risk" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="Risk buckets, 2025"
            subtitle="Deserts, one-source, watch list, public-radio sole source"
          >
            <div className="h-80 w-full">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={riskBars} margin={{ bottom: 48 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    dataKey="name"
                    tick={{ fontSize: 10 }}
                    interval={0}
                    angle={-25}
                    textAnchor="end"
                    height={70}
