"use client";

import { useMemo, useState } from "react";
import {
  Area,
  AreaChart,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Legend,
  Line,
  Pie,
  PieChart,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  ACCESS_TIER_PATH,
  CLOSURE_PATH,
  HEADLINE,
  NEWSPAPER_STOCK_PATH,
  OUTLET_MIX_2025,
  POPULATION_ACCESS_PATH,
  RISK_BUCKETS_2025,
  RURAL_URBAN_CONTRAST,
  SOURCE_NOTE,
  STATE_DESERT_RANKS,
  fmt1,
  fmtInt,
  statesByZeroDesc,
  statesByZeroShareDesc,
} from "@/data/us-counties-with-no-local-news-outlet-2026-data";

// viz-types: stacked access areas, state bars, outlet pie, rural??digital scatter, newspaper+closure composed, risk bars | layout: default

type ViewId = "access" | "states" | "ecosystem" | "risk";
type StateMetric = "zero" | "share" | "one";
type RegionFilter = "all" | "South" | "Midwest" | "West" | "Northeast";

const NAVY = "#0f172a";
const TEAL = "#0d9488";
const AMBER = "#d97706";
const ROSE = "#e11d48";
const SLATE = "#64748b";
const INDIGO = "#4f46e5";
const SKY = "#0284c8";

const REGION_COLORS: Record<string, string> = {
  South: ROSE,
  Midwest: INDIGO,
  West: TEAL,
  Northeast: AMBER,
};

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </span>
      <div className="inline-flex flex-wrap rounded-lg border border-slate-200 bg-white p-0.5">
        {options.map((o) => (
          <button
            key={o.id}
            type="button"
            onClick={() => onChange(o.id)}
            className={`rounded-md px-3 py-1.5 text-sm font-medium transition-colors ${
              value === o.id
                ? "bg-slate-900 text-white"
                : "text-slate-600 hover:bg-slate-50"
            }`}
          >
            {o.label}
          </button>
        ))}
      </div>
    </div>
  );
}

export function UsCountiesWithNoLocalNewsOutlet2026Dashboard() {
  const [view, setView] = useState<ViewId>("access");
  const [stateMetric, setStateMetric] = useState<StateMetric>("zero");
  const [region, setRegion] = useState<RegionFilter>("all");

  const accessSeries = useMemo(
    () =>
      ACCESS_TIER_PATH.map((r) => ({
        year: r.year,
        Zero: r.zero,
        One: r.one,
        "Two+": r.twoPlus,
        zeroOrOne: r.zero + r.one,
      })),
    [],
  );

  const stateBars = useMemo(() => {
    let rows =
      stateMetric === "share" ? statesByZeroShareDesc() : statesByZeroDesc();
    if (region !== "all") {
      rows = rows.filter((r) => r.region === region);
    }
    if (stateMetric === "one") {
      rows = [...rows].sort(
        (a, b) => b.oneSourceCounties - a.oneSourceCounties,
      );
    }
    return rows.map((r) => ({
      name: r.abbr,
      full: r.state,
      value:
        stateMetric === "zero"
          ? r.zeroCounties
          : stateMetric === "share"
            ? r.zeroShareOfStatePct
            : r.oneSourceCounties,
      fill: REGION_COLORS[r.region],
      region: r.region,
    }));
  }, [stateMetric, region]);

  const popSeries = useMemo(
    () =>
      POPULATION_ACCESS_PATH.map((r) => ({
        year: r.year,
        "Limited local news": r.limitedLocalNewsM,
        "Limited newspaper": r.limitedNewspaperM,
      })),
    [],
  );

  const newspaperClosure = useMemo(
    () =>
      NEWSPAPER_STOCK_PATH.map((n) => {
        const c = CLOSURE_PATH.find((x) => x.year === n.year);
        return {
          year: n.year,
          Newspapers: n.newspapers,
          Closures: c?.closures ?? null,
        };
      }),
    [],
  );

  const scatterRural = useMemo(
    () =>
      RURAL_URBAN_CONTRAST.map((r) => ({
        name: r.label,
        x: r.desertSharePct,
        y: r.digitalOutletSharePct,
        z: r.newspaperLossSharePct,
      })),
    [],
  );

  const pieData = useMemo(
    () =>
      OUTLET_MIX_2025.map((o) => ({
        name: o.label,
        value: o.count,
      })),
    [],
  );

  const riskBars = useMemo(
    () =>
      RISK_BUCKETS_2025.map((r) => ({
        name: r.label,
        counties: r.counties,
      })),
    [],
  );

  const pieColors = [NAVY, TEAL, SKY, AMBER, INDIGO];

  return (
    <div className="w-full space-y-6">
      <div className="rounded-xl border border-slate-200 bg-gradient-to-br from-slate-900 via-slate-800 to-slate-900 px-5 py-6 text-white sm:px-8">
        <p className="text-xs font-semibold uppercase tracking-widest text-teal-300">
          Local information ?? county access
        </p>
        <h2 className="mt-2 text-2xl font-bold tracking-tight sm:text-3xl">
          {fmtInt(HEADLINE.zeroOrOneCounties2025)} U.S. counties have zero or
          one local news outlet
        </h2>
        <p className="mt-3 max-w-3xl text-sm leading-relaxed text-slate-300">
          Medill???s 2025 inventory finds {fmtInt(HEADLINE.zeroSourceCounties2025)}{" "}
          counties with no locally based source and{" "}
          {fmtInt(HEADLINE.oneSourceCounties2025)} with only one???together covering
          about {fmt1(HEADLINE.peopleLimitedAccessM2025)} million people. That is
          up from roughly {fmtInt(HEADLINE.zeroSourceCounties2005)} deserts and{" "}
          {fmt1(HEADLINE.peopleLimitedAccessM2005)} million people around 2005.
        </p>
        <div className="mt-5 grid grid-cols-2 gap-3 sm:grid-cols-4">
          {[
            {
              label: "Zero-source counties",
              value: fmtInt(HEADLINE.zeroSourceCounties2025),
            },
            {
              label: "One-source counties",
              value: fmtInt(HEADLINE.oneSourceCounties2025),
            },
            {
              label: "Newspapers vanished since ???05",
              value: `~${fmtInt(HEADLINE.newspapersVanishedSince2005)}`,
            },
            {
              label: "Rural share of deserts",
              value: `${HEADLINE.ruralDesertSharePct2025}%`,
            },
          ].map((k) => (
            <div
              key={k.label}
              className="rounded-lg border border-white/10 bg-white/5 px-3 py-2"
            >
              <p className="text-[10px] uppercase tracking-wide text-slate-400">
                {k.label}
              </p>
              <p className="mt-1 text-lg font-bold text-white">{k.value}</p>
            </div>
          ))}
        </div>
      </div>

      <div className="flex flex-wrap gap-4">
        <ToggleGroup
          label="View"
          value={view}
          onChange={setView}
          options={[
            { id: "access", label: "Access path" },
            { id: "states", label: "States" },
            { id: "ecosystem", label: "Outlet mix" },
            { id: "risk", label: "Risk & rural" },
          ]}
        />
        {view === "states" && (
          <>
            <ToggleGroup
              label="Metric"
              value={stateMetric}
              onChange={setStateMetric}
              options={[
                { id: "zero", label: "Zero outlets" },
                { id: "share", label: "% of state" },
                { id: "one", label: "One outlet" },
              ]}
            />
            <ToggleGroup
              label="Region"
              value={region}
              onChange={setRegion}
              options={[
                { id: "all", label: "All" },
                { id: "South", label: "South" },
                { id: "Midwest", label: "Midwest" },
                { id: "West", label: "West" },
                { id: "Northeast", label: "Northeast" },
              ]}
            />
          </>
        )}
      </div>

      {view === "access" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="Counties by local-outlet count"
            subtitle="Stacked tiers ?? Medill/UNC path (early years estimated)"
          >
            <div className="h-80 w-full">
              <ResponsiveContainer width="100%" height="100%">
                <AreaChart data={accessSeries}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="year" tick={{ fontSize: 12 }} />
                  <YAxis tick={{ fontSize: 12 }} />
                  <Tooltip />
                  <Legend />
                  <Area
                    type="monotone"
                    dataKey="Zero"
                    stackId="1"
                    stroke={ROSE}
                    fill={ROSE}
                    fillOpacity={0.85}
                  />
                  <Area
                    type="monotone"
                    dataKey="One"
                    stackId="1"
                    stroke={AMBER}
                    fill={AMBER}
                    fillOpacity={0.75}
                  />
                  <Area
                    type="monotone"
                    dataKey="Two+"
                    stackId="1"
                    stroke={SLATE}
                    fill={SLATE}
                    fillOpacity={0.35}
                  />
                </AreaChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="People with limited local news"
            subtitle="Millions ?? dual Medill frames (local vs newspaper-only)"
          >
            <div className="h-80 w-full">
              <ResponsiveContainer width="100%" height="100%">
                <ComposedChart data={popSeries}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="year" tick={{ fontSize: 12 }} />
                  <YAxis tick={{ fontSize: 12 }} unit="M" />
                  <Tooltip />
                  <Legend />
                  <Bar
                    dataKey="Limited local news"
                    fill={TEAL}
                    radius={[4, 4, 0, 0]}
                  />
                  <Line
                    type="monotone"
                    dataKey="Limited newspaper"
                    stroke={NAVY}
                    strokeWidth={2.5}
                    dot={{ r: 4 }}
                  />
                </ComposedChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {view === "states" && (
        <ChartCard
          title="High-desert states (desk ranks)"
          subtitle="Scaled to Medill???s 213 national zero-source total ?? estimated"
        >
          <div className="h-96 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={stateBars} layout="vertical" margin={{ left: 8 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis
                  type="number"
                  tick={{ fontSize: 12 }}
                  unit={stateMetric === "share" ? "%" : undefined}
                />
                <YAxis
                  type="category"
                  dataKey="name"
                  width={36}
                  tick={{ fontSize: 12 }}
                />
                <Tooltip
                  formatter={(v) =>
                    stateMetric === "share"
                      ? `${fmt1(Number(v))}%`
                      : fmtInt(Number(v))
                  }
                  labelFormatter={(_, payload) =>
                    String(payload?.[0]?.payload?.full ?? "")
                  }
                />
                <Bar dataKey="value" radius={[0, 4, 4, 0]}>
                  {stateBars.map((d) => (
                    <Cell key={d.name} fill={d.fill} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
          {region !== "all" && stateBars.length === 0 && (
            <p className="text-sm text-slate-500">
              No ranked states in this region cut???try South or Midwest.
            </p>
          )}
        </ChartCard>
      )}

      {view === "ecosystem" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="Local news outlet mix, 2025"
            subtitle="Medill tracks ~8,000 outlets across five categories"
          >
            <div className="h-80 w-full">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={pieData}
                    dataKey="value"
                    nameKey="name"
                    cx="50%"
                    cy="50%"
                    innerRadius={55}
                    outerRadius={105}
                    paddingAngle={2}
                  >
                    {pieData.map((_, i) => (
                      <Cell key={i} fill={pieColors[i % pieColors.length]} />
                    ))}
                  </Pie>
                  <Tooltip formatter={(v) => fmtInt(Number(v))} />
                  <Legend />
                </PieChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Newspaper stock vs recent closures"
            subtitle="Stock path (left) ?? annual closures where timed (right)"
          >
            <div className="h-80 w-full">
              <ResponsiveContainer width="100%" height="100%">
                <ComposedChart data={newspaperClosure}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="year" tick={{ fontSize: 12 }} />
                  <YAxis
                    yAxisId="left"
                    tick={{ fontSize: 12 }}
                    domain={[4000, 8000]}
                  />
                  <YAxis
                    yAxisId="right"
                    orientation="right"
                    tick={{ fontSize: 12 }}
                    domain={[0, 160]}
                  />
                  <Tooltip />
                  <Legend />
                  <Area
                    yAxisId="left"
                    type="monotone"
                    dataKey="Newspapers"
                    stroke={NAVY}
                    fill={SKY}
                    fillOpacity={0.25}
                  />
                  <Line
                    yAxisId="right"
                    type="monotone"
                    dataKey="Closures"
                    stroke={ROSE}
                    strokeWidth={2.5}
                    connectNulls={false}
                    dot={{ r: 4 }}
                  />
                </ComposedChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {view === "risk" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="Risk buckets, 2025"
            subtitle="Deserts, one-source, watch list, public-radio sole source"
          >
            <div className="h-80 w-full">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={riskBars} margin={{ bottom: 48 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    dataKey="name"
                    tick={{ fontSize: 10 }}
                    interval={0}
                    angle={-25}
                    textAnchor="end"
                    height={70}
                  />
                  <YAxis tick={{ fontSize: 12 }} />
                  <Tooltip formatter={(v) => fmtInt(Number(v))} />
                  <Bar dataKey="counties" fill={INDIGO} radius={[4, 4, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Rural deserts vs digital outlets"
            subtitle="Bubble size = share of newspaper losses since 2005"
          >
            <div className="h-80 w-full">
              <ResponsiveContainer width="100%" height="100%">
                <ScatterChart margin={{ top: 8, right: 12, bottom: 8, left: 8 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    type="number"
                    dataKey="x"
                    name="Desert share"
                    unit="%"
                    tick={{ fontSize: 12 }}
                    domain={[0, 100]}
                    label={{
                      value: "% of news deserts",
                      position: "insideBottom",
                      offset: -2,
                      fontSize: 11,
                    }}
                  />
                  <YAxis
                    type="number"
                    dataKey="y"
                    name="Digital share"
                    unit="%"
                    tick={{ fontSize: 12 }}
                    domain={[0, 100]}
                    label={{
                      value: "% of digital outlets",
                      angle: -90,
                      position: "insideLeft",
                      fontSize: 11,
                    }}
                  />
                  <ZAxis type="number" dataKey="z" range={[80, 400]} />
                  <Tooltip
                    cursor={{ strokeDasharray: "3 3" }}
                    formatter={(v, name) => [
                      `${fmt1(Number(v))}%`,
                      String(name),
                    ]}
                    labelFormatter={(_, p) =>
                      String(p?.[0]?.payload?.name ?? "")
                    }
                  />
                  <Scatter data={scatterRural} fill={TEAL}>
                    {scatterRural.map((d) => (
                      <Cell
                        key={d.name}
                        fill={d.name.includes("rural") ? ROSE : TEAL}
                      />
                    ))}
                  </Scatter>
                </ScatterChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      <details className="rounded-lg border border-slate-200 bg-slate-50 px-4 py-3 text-sm text-slate-600">
        <summary className="cursor-pointer font-semibold text-slate-800">
          Sources & caveats
        </summary>
        <p className="mt-2 leading-relaxed">{SOURCE_NOTE}</p>
        <ul className="mt-2 list-inside list-disc space-y-1">
          {STATE_DESERT_RANKS.slice(0, 3).map((s) => (
            <li key={s.abbr}>
              {s.state}: ~{s.zeroCounties} zero-source ({s.confidence})
            </li>
          ))}
        </ul>
      </details>
    </div>
  );
}

