                  <YAxis tick={{ fontSize: 12 }} />
                  <Tooltip />
                  <Legend />
                  <Area
                    type="monotone"
                    dataKey="Zero"
                    stackId="1"
                    stroke={ROSE}
                    fill={ROSE}
                    fillOpacity={0.85}
                  />
                  <Area
                    type="monotone"
                    dataKey="One"
                    stackId="1"
                    stroke={AMBER}
                    fill={AMBER}
                    fillOpacity={0.75}
                  />
                  <Area
                    type="monotone"
                    dataKey="Two+"
                    stackId="1"
                    stroke={SLATE}
                    fill={SLATE}
                    fillOpacity={0.35}
                  />
                </AreaChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="People with limited local news"
            subtitle="Millions ?? dual Medill frames (local vs newspaper-only)"
          >
            <div className="h-80 w-full">
              <ResponsiveContainer width="100%" height="100%">
                <ComposedChart data={popSeries}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="year" tick={{ fontSize: 12 }} />
                  <YAxis tick={{ fontSize: 12 }} unit="M" />
                  <Tooltip />
                  <Legend />
                  <Bar
                    dataKey="Limited local news"
                    fill={TEAL}
                    radius={[4, 4, 0, 0]}
                  />
                  <Line
                    type="monotone"
                    dataKey="Limited newspaper"
                    stroke={NAVY}
                    strokeWidth={2.5}
                    dot={{ r: 4 }}
                  />
                </ComposedChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {view === "states" && (
        <ChartCard
          title="High-desert states (desk ranks)"
          subtitle="Scaled to Medill???s 213 national zero-source total ?? estimated"
        >
          <div className="h-96 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={stateBars} layout="vertical" margin={{ left: 8 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis
                  type="number"
                  tick={{ fontSize: 12 }}
                  unit={stateMetric === "share" ? "%" : undefined}
                />
                <YAxis
                  type="category"
                  dataKey="name"
                  width={36}
                  tick={{ fontSize: 12 }}
                />
                <Tooltip
                  formatter={(v) =>
                    stateMetric === "share"
                      ? `${fmt1(Number(v))}%`
                      : fmtInt(Number(v))
                  }
                  labelFormatter={(_, payload) =>
                    String(payload?.[0]?.payload?.full ?? "")
                  }
                />
                <Bar dataKey="value" radius={[0, 4, 4, 0]}>
                  {stateBars.map((d) => (
                    <Cell key={d.name} fill={d.fill} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
          {region !== "all" && stateBars.length === 0 && (
            <p className="text-sm text-slate-500">
              No ranked states in this region cut???try South or Midwest.
            </p>
          )}
        </ChartCard>
      )}

      {view === "ecosystem" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="Local news outlet mix, 2025"
            subtitle="Medill tracks ~8,000 outlets across five categories"
          >
            <div className="h-80 w-full">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={pieData}
                    dataKey="value"
                    nameKey="name"
                    cx="50%"
                    cy="50%"
                    innerRadius={55}
                    outerRadius={105}
                    paddingAngle={2}
                  >
                    {pieData.map((_, i) => (
                      <Cell key={i} fill={pieColors[i % pieColors.length]} />
                    ))}
                  </Pie>
                  <Tooltip formatter={(v) => fmtInt(Number(v))} />
                  <Legend />
                </PieChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Newspaper stock vs recent closures"
            subtitle="Stock path (left) ?? annual closures where timed (right)"
          >
            <div className="h-80 w-full">
              <ResponsiveContainer width="100%" height="100%">
                <ComposedChart data={newspaperClosure}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="year" tick={{ fontSize: 12 }} />
                  <YAxis
                    yAxisId="left"
                    tick={{ fontSize: 12 }}
                    domain={[4000, 8000]}
                  />
                  <YAxis
                    yAxisId="right"
                    orientation="right"
                    tick={{ fontSize: 12 }}
                    domain={[0, 160]}
                  />
                  <Tooltip />
                  <Legend />
                  <Area
                    yAxisId="left"
                    type="monotone"
                    dataKey="Newspapers"
                    stroke={NAVY}
                    fill={SKY}
                    fillOpacity={0.25}
                  />
                  <Line
                    yAxisId="right"
                    type="monotone"
                    dataKey="Closures"
                    stroke={ROSE}
                    strokeWidth={2.5}
                    connectNulls={false}
                    dot={{ r: 4 }}
                  />
                </ComposedChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {view === "risk" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="Risk buckets, 2025"
            subtitle="Deserts, one-source, watch list, public-radio sole source"
          >
            <div className="h-80 w-full">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={riskBars} margin={{ bottom: 48 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    dataKey="name"
                    tick={{ fontSize: 10 }}
                    interval={0}
                    angle={-25}
                    textAnchor="end"
                    height={70}
                  />
                  <YAxis tick={{ fontSize: 12 }} />
                  <Tooltip formatter={(v) => fmtInt(Number(v))} />
